/**
 * Typed codecs for the Leash contracts.
 *
 * The contract specs are vendored from the release WASM builds (`specs.ts`, regenerated by
 * `pnpm --filter @leash/sdk specs`) and interpreted by `contract.Spec` of the Stellar SDK.
 * Generated binding packages were not used: they pin their own SDK version, ship browser
 * polyfills and re-export the whole SDK, which does not fit this strict ESM workspace.
 */
import { Address, contract, scValToBigInt, xdr } from "@stellar/stellar-sdk";
import * as specs from "./specs.js";

export type ContractName = keyof typeof specs;

const cache = new Map<ContractName, contract.Spec>();

export function spec(name: ContractName): contract.Spec {
  let found = cache.get(name);
  if (!found) {
    found = new contract.Spec(specs[name]);
    cache.set(name, found);
  }
  return found;
}

/** Spec type of a user-defined contract type, e.g. `PolicyV2`. */
export const udt = (name: string): xdr.ScSpecTypeDef =>
  xdr.ScSpecTypeDef.scSpecTypeUdt(new xdr.ScSpecTypeUdt({ name }));

/** Encodes `value` as the contract type `type`, with every map sorted as the host requires. */
export function encode(name: ContractName, value: unknown, type: xdr.ScSpecTypeDef): xdr.ScVal {
  return sortMaps(spec(name).nativeToScVal(value, type));
}

/** Decodes `value` as the contract type `type` (maps come back as `[key, value]` arrays). */
export function decode<T>(name: ContractName, value: xdr.ScVal, type: xdr.ScSpecTypeDef): T {
  return spec(name).scValToNative(value, type) as T;
}

/** Return value of `fn`, unwrapping a `Result` return type. */
export function decodeResult<T>(name: ContractName, fn: string, value: xdr.ScVal): T {
  const [output] = spec(name).getFunc(fn).outputs;
  if (!output) return null as T;
  const type = output.type === "scSpecTypeResult" ? output.value.okType : output;
  return decode<T>(name, value, type);
}

/** Arguments of `fn`, named as in the contract. */
export function encodeArgs(name: ContractName, fn: string, args: Record<string, unknown>): xdr.ScVal[] {
  return spec(name).funcArgsToScVals(fn, args).map(sortMaps);
}

const rank = (value: xdr.ScVal) => xdr.ScValType[value.type].value;

function compareBytes(a: Uint8Array, b: Uint8Array): number {
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const diff = (a[i] as number) - (b[i] as number);
    if (diff !== 0) return diff < 0 ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

const sign = (diff: bigint) => (diff < 0n ? -1 : diff > 0n ? 1 : 0);

/**
 * Soroban host order of two values: by type, then by value (numbers numerically, symbols,
 * strings and bytes lexicographically, addresses by their XDR, vectors element-wise).
 */
export function compareScVal(a: xdr.ScVal, b: xdr.ScVal): number {
  const byType = rank(a) - rank(b);
  if (byType !== 0) return byType < 0 ? -1 : 1;
  switch (a.type) {
    case "scvBool":
    case "scvU32":
    case "scvI32":
      return sign(BigInt(Number(a.value)) - BigInt(Number(b.value)));
    case "scvU64":
    case "scvI64":
    case "scvU128":
    case "scvI128":
    case "scvU256":
    case "scvI256":
    case "scvTimepoint":
    case "scvDuration":
      return sign(scValToBigInt(a) - scValToBigInt(b));
    case "scvSymbol":
    case "scvString":
    case "scvBytes":
      return compareBytes(toBytes(a.value), toBytes(b.value));
    case "scvAddress":
      return compareBytes(a.value.toXDR(), (b.value as typeof a.value).toXDR());
    case "scvVec": {
      const [left, right] = [a.value ?? [], (b.value as xdr.ScVal[] | null) ?? []];
      for (let i = 0; i < Math.min(left.length, right.length); i++) {
        const diff = compareScVal(left[i] as xdr.ScVal, right[i] as xdr.ScVal);
        if (diff !== 0) return diff;
      }
      return left.length === right.length ? 0 : left.length < right.length ? -1 : 1;
    }
    default:
      return compareBytes(a.toXDR(), b.toXDR());
  }
}

function toBytes(value: unknown): Uint8Array {
  if (typeof value === "string") return new TextEncoder().encode(value);
  if (value instanceof Uint8Array) return value;
  return new TextEncoder().encode(String(value));
}

/** Sorts every map nested in `value` into host order, which `Map` arguments require. */
export function sortMaps(value: xdr.ScVal): xdr.ScVal {
  switch (value.type) {
    case "scvVec":
      return xdr.ScVal.scvVec((value.value ?? []).map(sortMaps));
    case "scvMap":
      return xdr.ScVal.scvMap((value.value ?? [])
        .map(entry => new xdr.ScMapEntry({ key: sortMaps(entry.key), val: sortMaps(entry.val) }))
        .sort((x, y) => compareScVal(x.key, y.key)));
    default:
      return value;
  }
}

export const addressVal = (value: string): xdr.ScVal => new Address(value).toScVal();
